import json
with open('/app/resources/treasury_bulletin_2010_06.json') as f:
    data = json.load(f)

# Search for December 2010 data in the JSON
def search_dates(d, path=''):
    if isinstance(d, dict):
        for k, v in d.items():
            if '2010' in str(k) and 'Dec' in str(k):
                print(f'Found: {path}/{k}')
            search_dates(v, f'{path}/{k}')
    elif isinstance(d, list):
        for i, item in enumerate(d):
            search_dates(item, f'{path}[{i}]')

search_dates(data)
